class Solution {
    public String findTheString(int[][] lcp){
        int n=lcp.length;
        char[] chars=new char[n];
        char next='a';
        for(int i=0;i<n;i++){
            if(chars[i]!=0)continue;
            if(next>'z')return "";
            for(int j=i;j<n;j++)if(lcp[i][j]>0)chars[j]=next;
            next++;
        }
        int[][] actual=new int[n+1][n+1];
        for(int i=n-1;i>=0;i--)for(int j=n-1;j>=0;j--){
            if(chars[i]==chars[j])actual[i][j]=actual[i+1][j+1]+1;
            if(actual[i][j]!=lcp[i][j])return "";
        }
        return new String(chars);
    }
}

